// Draft: the specification is not approved: there is no records/approvals/1.0.0.yaml beside the specification; this file is not the approved output.
// The shell of the application: the title, the language choice, the menu,
// the message an event left, and the page the route opens, drawn by the
// component of its kind behind the guard, from the data files app.js at
// the root imported. mount(el, { pages, custom, hooks }) mounts it.

import { application } from "../config/application.js";
import { ContentPage } from "./ContentPage.js";
import { FormPage } from "./FormPage.js";
import { Guard } from "./Guard.js";
import { Home } from "./Home.js";
import { language } from "./language.js";
import { LanguageChoice } from "./LanguageChoice.js";
import { ListPage } from "./ListPage.js";
import { Menu } from "./Menu.js";
import { Notice } from "./Notice.js";
import { hrefOf, location, match } from "./router.js";
import { say, textsOf } from "./texts.js";
import { TaskPage } from "./TaskPage.js";
import { ViewPage } from "./ViewPage.js";
import { computed, createApp, h, html, reactive, watchEffect } from "./vue.js";

const byKind = { list: ListPage, form: FormPage, view: ViewPage, content: ContentPage };

/**
 * A module the project writes, imported when its page opens, so one that
 * is missing or fails is said on that page alone and the application is
 * never blank: load answers the module, read picks what the page needs
 * from it, and draw draws the page with it.
 */
const Loaded = {
  name: "Loaded",
  props: { load: { type: Function, required: true }, pattern: { type: String, required: true }, read: { type: Function, required: true }, draw: { type: Function, required: true }, texts: { type: Object, required: true } },
  setup(props) {
    const state = reactive({ value: undefined, failed: undefined });
    props
      .load()
      .then((module) => {
        state.value = props.read(module);
      })
      .catch((error) => {
        state.failed = say(props.texts, { text: "screens.missingModule", pattern: props.pattern }) + " " + (error instanceof Error ? error.message : String(error));
      });
    return () => {
      if (state.failed !== undefined) {
        return html`<p role="alert" class="screens-refused">${state.failed}</p>`;
      }
      if (state.value === undefined) {
        return html`<p role="status" class="screens-loading">${say(props.texts, "screens.loading")}</p>`;
      }
      return props.draw(state.value);
    };
  },
};

const Shell = {
  name: "Shell",
  props: { pages: { type: Object, required: true }, custom: { type: Object, required: true }, hooks: { type: Object, required: true } },
  setup(props) {
    const texts = computed(() => textsOf(language.value));
    const found = computed(() => match(props.pages, location.value.path));
    watchEffect(() => {
      const page = found.value?.page;
      document.title = page === undefined ? application.title : say(texts.value, page.schema.title) + " · " + application.title;
    });

    function content() {
      const t = texts.value;
      const route = found.value;
      if (route === undefined) {
        if (location.value.path === "/") {
          return application.homes !== undefined ? h(Home, { texts: t }) : null;
        }
        return html`<p role="alert" class="screens-refused">${say(t, { text: "screens.missingPage", pattern: location.value.path })}</p>`;
      }
      const { page, parameters } = route;
      // The key makes each page its own instance: two pages of one kind in
      // a row would otherwise share one, and the first's state would stay.
      const common = { key: page.name + " " + JSON.stringify(parameters), schema: page.schema, texts: t, routes: page.routes, parameters };
      if (page.kind === "task") {
        return h(TaskPage, common);
      }
      let drawn;
      switch (page.kind) {
        case "custom":
          drawn = h(Loaded, {
            load: props.custom[page.name] ?? (() => Promise.reject(new Error("app.js knows no screen for " + page.name))),
            pattern: "custom/" + page.name + ".js",
            read: (module) => module.default,
            draw: (Screen) => h(Screen, common),
            texts: t,
          });
          break;
        case "form":
          drawn =
            props.hooks[page.name] === undefined
              ? h(FormPage, common)
              : h(Loaded, {
                  load: props.hooks[page.name],
                  pattern: "hooks/" + page.name + ".js",
                  read: (module) => module,
                  draw: (hooks) => h(FormPage, { ...common, hooks }),
                  texts: t,
                });
          break;
        default:
          drawn = h(byKind[page.kind] ?? ContentPage, common);
      }
      return h(Guard, { permission: page.permission, texts: t }, () => drawn);
    }

    return () => html`<div class="screens-shell" lang=${language.value}>
      <header class="screens-header">
        <a class="screens-title" href=${hrefOf("/")}>${application.title}</a>
        <${LanguageChoice} texts=${texts.value} />
      </header>
      <${Menu} texts=${texts.value} />
      <main id="main" class="screens-main">
        <${Notice} />
        ${content()}
      </main>
    </div>`;
  },
};

/** Mounts the application on el, with the pages' data, the project's custom screens and its hooks, each a loader of its module. */
export function mount(el, { pages, custom = {}, hooks = {} }) {
  const app = createApp(Shell, { pages, custom, hooks });
  app.mount(el);
  return app;
}
